SELECT FROM crm_messenger_conversation cv
LEFT JOIN sys_user u ON u.user_id = cv.user_id LEFT JOIN sys_dept d ON u.dept_id = d.dept_id
cv.tenant_id = #{tenantId}
AND cv.user_id IS NULL AND cv.status <> 'blocked'
AND cv.user_id = #{currentUserId} AND cv.status <> 'blocked'
AND cv.user_id IS NOT NULL AND cv.status <> 'blocked' ${params.dataScope}
AND cv.status = #{status}
AND (cv.psid ILIKE '%' || #{keyword} || '%' OR cv.profile_name ILIKE '%' || #{keyword} || '%' OR cv.owner ILIKE '%' || #{keyword} || '%' OR cv.last_message_preview ILIKE '%' || #{keyword} || '%')
AND cv.id = #{conversationId}
ORDER BY cv.last_message_at DESC NULLS LAST

