mapper.update:
UPDATE crm_messenger_conversation
SET contact_id = #{contactId}, update_time = now()
WHERE tenant_id = #{tenantId} AND psid = #{psid}

UPDATE crm_messenger_conversation
SET lead_id = #{leadId}, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

UPDATE crm_messenger_conversation SET last_message_at = #{lastMessageAt}, last_message_preview = #{lastMessagePreview},
last_outbound_at = #{lastOutboundAt},
update_time = now() WHERE id = #{id}

UPDATE crm_messenger_conversation
SET unread_count = 0, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

UPDATE crm_messenger_conversation
SET status = #{status}, update_time = now()
WHERE id = #{id} AND tenant_id = #{tenantId}

